#[cfg(test)]
mod m1_regression_tests {
    use super::*;
    #[test]
    fn m1_reject_negative_box_extent() {
        let data = [320.0, 320.0, -64.0, 64.0, 0.9];
        assert!(decode_yolo_detections(&data, 1, 1, 0.5, 0.45).is_empty());
    }
    #[test]
    fn m1_reject_nonfinite_geometry_and_scores() {
        for data in [
            [f32::NAN, 320.0, 64.0, 64.0, 0.9],
            [320.0, 320.0, 64.0, 64.0, f32::INFINITY],
        ] {
            assert!(decode_yolo_detections(&data, 1, 1, 0.5, 0.45).is_empty());
        }
    }
    #[test]
    fn m1_clipped_box_center_matches_visible_bounds() {
        let detections = decode_yolo_detections(&[630.0, 320.0, 100.0, 100.0, 0.9], 1, 1, 0.5, 0.45);
        let d = &detections[0];
        assert!((d.center.0 - (d.bbox[0] + d.bbox[2]) * 0.5).abs() < 1e-6);
    }
    #[test]
    fn m1_unknown_class_does_not_panic() {
        let mut data = vec![0.0; 15];
        data[..4].copy_from_slice(&[320.0, 320.0, 64.0, 64.0]);
        data[14] = 0.9;
        let detections = decode_yolo_detections(&data, 11, 1, 0.5, 0.45);
        assert_eq!(detections[0].class_name, "unknown");
    }
    #[test]
    fn m1_zero_classes_cannot_create_detection() {
        assert!(decode_yolo_detections(&[320.0, 320.0, 64.0, 64.0], 0, 1, 0.0, 0.45).is_empty());
    }
}

