#[cfg(test)]
mod m1_regression_tests {
    use super::*;
    fn target(x: f32, confidence: f32) -> Detection {
        Detection { class_id: 2, class_name: "target", confidence, bbox: [x - 0.05, 0.45, x + 0.05, 0.55], center: (x, 0.5) }
    }
    #[test]
    fn m1_flow_advances_box_and_center_together() {
        let mut point = TrackedPoint::new((0.3, 0.3), [0.2, 0.2, 0.4, 0.4], 0.9);
        let mut flow = FlowField::new(100, 100);
        flow.u.fill(10.0);
        point.propagate_flow(&flow);
        assert!((point.bbox[0] - 0.3).abs() < 1e-6);
        assert!((point.bbox[2] - 0.5).abs() < 1e-6);
        assert!((point.center.0 - 0.4).abs() < 1e-6);
    }
    #[test]
    fn m1_scene_cut_clears_old_targets_and_points() {
        let mut tracker = AnatomicalTracker::new();
        tracker.update_pose(&[target(0.5, 0.9)], None);
        tracker.point_tracker.seed_from_bbox([0.2, 0.2, 0.4, 0.4], "target", 4);
        tracker.update_pose_adaptive(None, None, None, false, 100, true);
        assert!(tracker.memory.tracked_target.is_none());
        assert!(tracker.memory.tracked_probe.is_none());
        assert!(tracker.point_tracker.trajectories.is_empty());
    }
    #[test]
    fn m1_confidence_change_does_not_replace_spatial_match() {
        let mut tracker = AnatomicalTracker::new();
        tracker.update_pose(&[target(0.3, 0.9)], None);
        tracker.update_pose(&[target(0.85, 0.99), target(0.3, 0.7)], None);
        assert!((tracker.memory.tracked_target.as_ref().unwrap().center.0 - 0.3).abs() < 1e-6);
    }
    #[test]
    fn m1_missing_detection_ages_without_flow() {
        let mut tracker = AnatomicalTracker::new();
        tracker.update_pose(&[target(0.5, 0.9)], None);
        tracker.update_pose(&[], None);
        assert_eq!(tracker.memory.tracked_target.as_ref().unwrap().frames_occluded, 1);
    }
}

