#[cfg(test)]
mod m1_regression_tests {
    use super::*;
    #[test]
    fn m1_degenerate_boxes_do_not_seed_points() {
        let mut tracker = TapPointTracker::new(TapTrackerConfig::default());
        tracker.seed_from_bbox([0.9, 0.2, 0.1, 0.8], "target", 4);
        tracker.seed_from_bbox([1.0, 1.0, 1.0, 1.0], "target", 4);
        assert!(tracker.trajectories.is_empty());
    }
    #[test]
    fn m1_zero_requested_mask_points_do_not_panic() {
        let mut tracker = TapPointTracker::new(TapTrackerConfig::default());
        tracker.seed_from_mask(&[255; 4], 2, 2, "target", 0);
        assert!(tracker.trajectories.is_empty());
    }
    #[test]
    fn m1_forward_flow_is_not_its_own_backward_flow() {
        let mut tracker = TapPointTracker::new(TapTrackerConfig::default());
        tracker.trajectories.push(PointTrajectory::new(0, (0.5, 0.5), "target"));
        let mut flow = FlowField::new(100, 100);
        flow.u.fill(10.0);
        tracker.step_frame(&flow, 33);
        assert_eq!(tracker.trajectories[0].forward_backward_error, 0.0);
    }
}

