#[cfg(test)]
mod m1_regression_tests {
    use super::*;
    #[test]
    fn m1_constant_displacement_never_invents_stroke() {
        let actions = extract_actions_full_range(&[42.0; 4], &[0, 100, 200, 300], 3.5, true);
        assert!(!actions.is_empty());
        assert!(actions.iter().all(|a| a.pos == actions[0].pos));
    }
    #[test]
    fn m1_monotonic_decreasing_motion_keeps_direction() {
        let actions = extract_actions_full_range(&[3.0, 2.0, 1.0, 0.0], &[0, 100, 200, 300], 3.5, false);
        assert!(actions.first().unwrap().pos > actions.last().unwrap().pos);
    }
    #[test]
    fn m1_trailing_pause_does_not_add_reversal() {
        let actions = extract_actions_full_range(&[0.0, 10.0, 0.0, 0.0, 0.0], &[0, 100, 200, 300, 400], 3.5, false);
        assert_eq!(actions.last().unwrap().pos, 0);
    }
    #[test]
    fn m1_keyframe_reduction_preserves_both_pause_boundaries() {
        for values in [[20.0, 40.0, 40.0, 40.0, 20.0], [40.0, 20.0, 20.0, 20.0, 40.0]] {
            let actions = extract_actions(&values, &[0, 100, 200, 300, 400], true);
            let start = actions.iter().find(|a| a.at == 100).expect("missing pause start");
            let end = actions.iter().find(|a| a.at == 300).expect("missing pause end");
            assert_eq!(start.pos, end.pos);
        }
    }
}

